"""Self-contained private Chucky Lab cockpit.

The page consumes only the compact server-side cockpit projection. It never
reads ChatGPT DOM content or connects to PostgreSQL from the browser.
"""

COCKPIT_HTML = """<!doctype html><html><head><title>Chucky Lab</title><meta name=viewport content="width=device-width,initial-scale=1"><style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif}body{margin:0;background:#07101b;color:#e8f0fb}main{max-width:1440px;margin:auto;padding:22px}.top{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.top h1{margin:0;font-size:24px}.muted{color:#9cadc7}.controls{margin-left:auto;display:flex;gap:8px;align-items:center}.controls input,button{background:#101f33;color:#e8f0fb;border:1px solid #315071;border-radius:8px;padding:9px}.controls button{background:#2869d8;font-weight:700;cursor:pointer}.grid{display:grid;gap:14px;margin-top:16px}.workers{grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}.panels{grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}.card,.panel{background:#0f1b2d;border:1px solid #263e5b;border-radius:12px;padding:15px}.card h2,.panel h2{font-size:14px;margin:0 0 12px}.line{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #203650;padding:8px 0;font-size:13px}.line:first-of-type{border-top:0}.tag{padding:3px 7px;border-radius:999px;font-weight:700;font-size:11px;background:#203959;color:#b9d4ff}.tag.error,.tag.blocked{background:#4e2130;color:#ffabb7}.tag.ready,.tag.running{background:#153c36;color:#7ee8c1}.tag.waiting{background:#453a1d;color:#ffe28b}ul{list-style:none;padding:0;margin:0}li{padding:9px 0;border-top:1px solid #203650;font-size:13px}.label{font-size:11px;text-transform:uppercase;color:#8fa6c5;letter-spacing:.08em}.hero{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}.metric{min-width:150px}.metric b{font-size:20px}.empty{color:#93a6bd;font-style:italic}code{color:#b7d0ff;word-break:break-all}.warning{color:#ffd781}@media(max-width:620px){main{padding:14px}.controls{margin-left:0;width:100%}.controls input{flex:1}}
</style></head><body><main><header class=top><div><h1>CHUCKY LAB <span class=muted>/ GPU-LAB</span></h1><div id=subtitle class=muted>Choose a Research OS project</div></div><div class=controls><input id=project placeholder="Research project ID" aria-label="Research project ID"><button id=load>Open cockpit</button><button id=autopilot disabled>AUTOPILOT</button><button id=continue disabled>AUTO CONTINUE</button><button id=pause disabled>PAUSE LAB</button></div></header><section id=summary class="hero empty">No project loaded.</section><section id=workers class="grid workers"></section><section class="grid panels"><article class=panel><h2>GPU JOBS</h2><ul id=gpus><li class=empty>Load a project.</li></ul></article><article class=panel><h2>READY WORK</h2><ul id=ready><li class=empty>Load a project.</li></ul></article><article class=panel><h2>RECENT EVENTS</h2><ul id=events><li class=empty>Load a project.</li></ul></article><article class=panel><h2>WORKER TURNS</h2><ul id=turns><li class=empty>Load a project.</li></ul></article></section></main><script>
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));const tag=v=>`<span class="tag ${esc(String(v||'').toLowerCase().replaceAll('_','-'))}">${esc(v||'UNKNOWN')}</span>`;let projectId=new URLSearchParams(location.search).get('project_id')||'',csrfToken='',controls={};$('#project').value=projectId;const list=(items,render,empty)=>items?.length?items.map(render).join(''):`<li class=empty>${empty}</li>`;
function render(data){const s=data.lab_state||{},c=data.controls||{},runs=new Map((data.browser_runtimes||[]).map(r=>[r.worker_id,r]));$('#subtitle').textContent=`${s.project?.name||'Project'} · ${s.project?.id||projectId}`;$('#summary').className='hero';$('#summary').innerHTML=[['AUTOPILOT',c.autopilot_enabled?'ON':'OFF'],['AUTO CONTINUE',c.auto_continue_enabled?'ON':'OFF'],['SCHEDULING',c.paused?'PAUSED':'ACTIVE'],['READY WORK',(s.ready_work_items||[]).length],['GPU RUNS',(s.gpu_activity||[]).length]].map(([a,b])=>`<article class="card metric"><div class=label>${a}</div><b>${esc(b)}</b></article>`).join('');$('#workers').innerHTML=list(s.active_workers,w=>{const r=runs.get(w.worker_id)||{};return `<article class=card><h2>${esc(w.display_name||w.worker_id)}</h2><div class=line><span>LAB</span>${tag(w.status)}</div><div class=line><span>WEB</span>${tag(r.status||'UNATTACHED')}</div><div class=line><span>ROLE</span><b>${esc(w.active_role||'IDLE')}</b></div><div class=line><span>WORK</span><code>${esc(w.current_work_item_id||'—')}</code></div><div class=line><span>LEASE / HEARTBEAT</span><span>${esc(w.last_heartbeat_at||'—')}</span></div>${r.last_error?`<div class="warning">${esc(r.last_error)}</div>`:''}</article>`},'No active workers.');$('#gpus').innerHTML=list(s.gpu_activity,x=>`<li>${tag(x.status)} <code>${esc(x.id)}</code><br>${esc(x.data?.label||x.data?.job_id||'ExperimentRun')}</li>`,'No active GPU execution.');$('#ready').innerHTML=list(s.ready_work_items,x=>`<li>${tag(x.scientific_role)} <b>${esc(x.title)}</b><br><span class=muted>priority ${esc(x.priority)} · cost ${esc(x.estimated_cost??'—')}</span></li>`,'No useful work is ready.');$('#events').innerHTML=list(s.recent_events,x=>`<li>${esc(x.event_type)}<br><span class=muted>${esc(x.created_at||'')}</span></li>`,'No recent events.');$('#turns').innerHTML=list(data.recent_turns,x=>`<li>${tag(x.outcome)} ${esc(x.summary||'No summary')}<br><span class=muted>${esc(x.created_at||'')}</span></li>`,'No worker turns recorded.');}
function renderControls(next){controls=next;for(const id of ['autopilot','continue','pause'])$('#'+id).disabled=false;$('#autopilot').textContent=`AUTOPILOT ${next.autopilot_enabled?'ON':'OFF'}`;$('#continue').textContent=`AUTO CONTINUE ${next.auto_continue_enabled?'ON':'OFF'}`;$('#pause').textContent=next.paused?'RESUME LAB':'PAUSE LAB'}async function setControl(update){if(!projectId||!csrfToken)return;const r=await fetch('/cockpit/controls',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify({project_id:projectId,...update})});if(!r.ok)throw Error((await r.json()).error||'Control update failed');await load()}async function load(){projectId=$('#project').value.trim();if(!projectId)return;history.replaceState(null,'',`/?project_id=${encodeURIComponent(projectId)}`);try{const r=await fetch(`/cockpit/state?project_id=${encodeURIComponent(projectId)}`),data=await r.json();if(!r.ok)throw Error(data.error||'Could not load cockpit');render(data);renderControls(data.controls||{})}catch(e){$('#subtitle').textContent=e.message}}$('#load').onclick=load;$('#project').addEventListener('keydown',e=>{if(e.key==='Enter')load()});$('#autopilot').onclick=()=>setControl({autopilot_enabled:!controls.autopilot_enabled}).catch(e=>$('#subtitle').textContent=e.message);$('#continue').onclick=()=>setControl({auto_continue_enabled:!controls.auto_continue_enabled}).catch(e=>$('#subtitle').textContent=e.message);$('#pause').onclick=()=>setControl({paused:!controls.paused}).catch(e=>$('#subtitle').textContent=e.message);fetch('/cockpit/session').then(r=>r.json()).then(x=>{csrfToken=x.csrf_token||''});if(projectId)load();setInterval(()=>{if(projectId)load()},5000);
</script></main></body></html>"""
